mapper.select:

where state in (1,2,3,4,5)

 and top_name like concat('%', #{topName}, '%')

 and user_name like concat('%', #{userName}, '%')
 and state = #{state}
 and YEAR(signing_data) = #{year}

${params.dataScope}

order  by createtime desc

select s.id,u.user_name userName, s.user_id, s.top_name, s.top_type,  s.signing_data, s.validity_Date,s.first_person_id,  s.second_person_id, s.third_person_id, s.fourth_person_id,  s.amount, s.contract, s.filing,s.filingurl,s.agreeurl ,s.state
from sci_horizontal_apply s  left join sys_user u on  s.user_id=u.user_id
where s.id = #{id}

mapper.update:
update sci_horizontal_apply
filingurl=#{filing}, agreeurl=#{contract}, state=#{state},
where id=#{id}
